import{_ as t,c as e,o as n,ae as i}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"Table Row Color","description":"Table Row Color","frontmatter":{"title":"Table Row Color","description":"Table Row Color"},"headers":[],"relativePath":"guide/styling-design/tables-row-color.md","filePath":"guide/styling-design/tables-row-color.md"}'),a={name:"guide/styling-design/tables-row-color.md"};function s(r,o,l,c,g,w){return n(),e("div",null,[...o[0]||(o[0]=[i('<h1 id="table-row-color" tabindex="-1">Table Row Color <a class="header-anchor" href="#table-row-color" aria-label="Permalink to &quot;Table Row Color&quot;">​</a></h1><p>Ninja Tables allows you to personalize your tables in various ways, including altering <strong>Row</strong> <strong>Colors</strong> to enhance visual appeal and clarity. Here in this article, we will show how you can modify Row colors using Ninja Tables.</p><h2 id="accessing-row-editing" tabindex="-1"><strong>Accessing Row Editing</strong> <a class="header-anchor" href="#accessing-row-editing" aria-label="Permalink to &quot;**Accessing Row Editing**&quot;">​</a></h2><p>Start by navigating to your Table where you want to make changes and go to the specific Row you wish to customize. Click on the <strong>Pencil</strong> icon, representing the <strong>Edit</strong> option. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-access-row-editing-1024x475.webp" alt="New Ui access row editing"> By clicking the pencil icon, a popup window will appear, presenting editing options for the selected row. At the bottom of this window, locate and click on the &quot;<strong>Settings</strong>&quot; icon to enter advanced customization for this specific row. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-update-row-settings-1024x682.webp" alt="New Ui update row settings"></p><h2 id="customizing-row-colors" tabindex="-1">**Customizing Row Colors ** <a class="header-anchor" href="#customizing-row-colors" aria-label="Permalink to &quot;**Customizing Row Colors **&quot;">​</a></h2><p>There are several customization choices available in the Settings section, including the <strong>Row</strong> <strong>Background color</strong>, <strong>Row Text Color</strong>, and **Cell Color Customization **settings.  To make changes, click the color box next to the Row or particular <strong>Column Cell Color</strong> you want to change. A color scheme will appear, allowing you to choose your favorite shade. After making your selection, click <strong>Ok</strong> to confirm. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-row-color-settings-1024x891.webp" alt="New Ui row color settings"> Lastly, click on the <strong>Update</strong> button to save your changes. After the table has been saved, visit it in the front-end interface to see how the color changes have been smoothly included, improving the readability and overall presentation. <img src="https://ninjatables.com/wp-content/uploads/2024/04/Ninja-Tables-Pro-Row-Color-Preview.webp" alt="Ninja Tables Row Color Preview"></p>',6)])])}const p=t(a,[["render",s]]);export{h as __pageData,p as default};
